(85, 'ptBR', 'Terrano', 'Terrano', 'terrano', 'terrano', 'Terrano', '', 'terrano', '', 'Recém-libertados dos éditos que os prendiam, os novos terranos aventuram-se com curiosidade sem limites para explorar o mundo e juntar-se à Aliança.', 'Terrano', '', 'terrano', '', 56647),
(84, 'ptBR', 'Terrano', 'Terrano', 'terrano', 'terrano', 'Terrano', '', 'terrano', '', 'Recém-libertados dos éditos que os prendiam, os novos terranos aventuram-se com curiosidade sem limites para explorar o mundo e juntar-se à Horda.', 'Terrano', '', 'terrano', '', 56647),
(36, 'ptBR', 'Orc Mag\'har', 'Orc Mag\'har', 'orc', 'orquisa', 'Mag\'har', '', 'Mag\'har', '', 'Clãs rivais no passado, os orcs incorruptos de Draenor agora lutam lado a lado como os ferozes Mag\'har.', 'Orc', '', 'orc', '', 56647);
