INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'ptBR', 'Brann Barbabronze', 'Companheiro de Imersão Confiável', 56647),
(2600, 'ptBR', 'Os Fios Cortados', 'O tumultuado reinado da Rainha Ansurek não está livre de detratores. Os Fios Cortados trabalham de forma inteligente e silenciosa nos bastidores para desfiar a tapeçaria do governo implacável de Ansurek.', 56647),
(2596, 'ptBR', 'Os Fios Cortados (Paragão)', 'O tumultuado reinado da Rainha Ansurek não está livre de detratores. Os Fios Cortados trabalham de forma inteligente e silenciosa nos bastidores para desfiar a tapeçaria do governo implacável de Ansurek.', 56647),
(2606, 'ptBR', 'Altagrota', 'Controla o comportamento das criaturas na Altagrota da Cidade das Tramas', 56647),
(2649, 'ptBR', 'O General (Paragão)', 'Outrora líder militar mais renomado de Azj-Kahet, Anub\'azal foi preterido em favor de um dos queridos Ascendidos de Ansurek. Isso não será tolerado.', 56647),
(2648, 'ptBR', 'A Fiandeira (Paragão)', 'Outrora Fiandeira Real, a Viúva Arak\'nai agora observa atentamente sua antiga casa com olhar crítico. Com uma rede de fofocandeiros e espiões à disposição, quase nada passa despercebido por ela.', 56647),
(2647, 'ptBR', 'O Vizir (Paragão)', 'Na posição mais perigosa de todas, o Executor Nizrek passa os dias como conselheiro mais leal da Rainha Ansurek. Felizmente, Ansurek ainda não descobriu que ele usa o restante de seu tempo para acabar com o reinado dela.', 56647),
(2607, 'ptBR', 'O Vizir', 'Na posição mais perigosa de todas, o Executor Nizrek passa os dias como conselheiro mais leal da Rainha Ansurek. Felizmente, Ansurek ainda não descobriu que ele usa o restante de seu tempo para acabar com o reinado dela.', 56647),
(2605, 'ptBR', 'O General', 'Outrora líder militar mais renomado de Azj-Kahet, Anub\'azal foi preterido em favor de um dos queridos Ascendidos de Ansurek. Isso não será tolerado.', 56647),
(2601, 'ptBR', 'A Fiandeira', 'Outrora Fiandeira Real, a Viúva Arak\'nai agora observa atentamente sua antiga casa com olhar crítico. Com uma rede de fofocandeiros e espiões à disposição, quase nada passa despercebido por ela.', 56647);
