(30153, 'ptBR', 'Seção 67', '$[!16\n\nNo modo Mítico, jogadores atingidos por este feitiço criam um |cFF2959D3|Hspell:460263|h[Grânulo de Raiva Implacável]|h|r ou um |cFF2959D3|Hspell:460357|h[Grânulo de Paranoia Irascível]|h|r.$]', 56647),
(30149, 'ptBR', 'Seção 64', '', 56647),
(30040, 'ptBR', 'Seção 59', '$[!17\n\nNo modo LR, |cFF2959D3|Hspell:438708|h[Enxame Aguilhoante]|h|r só será transferido para Takazj quando dissipado.$]', 56647),
