INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(776, 'ptBR', 'Rylak Espectral Veloz', '|cFFFFD200Legado|r', 'Até mesmo os mortos precisam de uma caroninha de vez em quando.', 56647),
(2188, 'ptBR', 'Kah, Lenda das Profundezas', '|cFFFFD200Conquista: |rPesca Presto|n|cFFFFD200Categoria: |rPesca', '', 56647),
(2218, 'ptBR', 'Morcevil do Gladiador Forjado', '|cFFFFD200Conquista:|r Gladiador: Elite da Série 1 de The War Within|n|cFFFFD200Categoria:|r Jogador x Jogador', 'Despertos das cavernas no campo de batalha e blindados para a briga.', 56647),
(2159, 'ptBR', 'Unidade de Defesa Mecânica 1-11', '|cFFFFD200Tesouro: |rBaú Desperto|n|cFFFFD200Área: |rFosso Ressonante', 'Um dos vários trajes de meca criados para proteger a Máquina. Após longos anos de serviço, não serve mais para o combate, mas dá um belo possante para desfilar por aí.', 56647),
(2209, 'ptBR', 'Rinolama Carmesim', '|cFFFFD200Comerciante: |rCerista Esquico|n|cFFFFD200Área: |rFosso Ressonante|n|cFFFFD200Custo: |r8125|Hcurrency:2815|h|TInterface\\ICONS\\SPELL_AZERITE_ESSENCE14.BLP:0|t|h', 'A Assembleia do Fosso decidiu permitir que você tenha acesso a um de seus rinolamas mais leais. Eles são usados com frequência como montaria pelos kobolds.', 56647);
